package com.bnfix.ubm.domains.subscription;
import com.bnfix.ubm.domains.benefit.*; import com.bnfix.ubm.domains.employee.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CompanyBenefitAssignmentService {private final EmployeeRepository employees;private final SubscriptionRepository subscriptions;private final BenefitRepository benefits;public CompanyBenefitAssignmentService(EmployeeRepository e,SubscriptionRepository s,BenefitRepository b){employees=e;subscriptions=s;benefits=b;} @Transactional public void assignBenefitToActiveEmployees(Benefit b){employees.findByCompanyIdAndActive(b.getProvider().id,EmployeeStatus.ACTIVE).forEach(e->ensure(e,b));} @Transactional public void assignActiveCompanyBenefits(Employee e){benefits.findByProviderIdAndActiveTrue(e.getCompany().id).forEach(b->ensure(e,b));} private void ensure(Employee e,Benefit b){if(!subscriptions.existsByEmployeeAndBenefit(e.id,b.id))subscriptions.save(Subscription.builder(b,e).build());}}
